type memberPatterns struct {
	procsByRepo map[string][]procedureRecord
	pracsByRepo map[string][]practiceRecord
	tasksByRepo map[string][]taskCandidate
	repoOrder   []string
	warnings    []string
}

func loadMemberPatterns(opts Options, manifest workspaceManifest) (memberPatterns, error) {
	m := memberPatterns{procsByRepo: map[string][]procedureRecord{}, pracsByRepo: map[string][]practiceRecord{}, tasksByRepo: map[string][]taskCandidate{}}
	repos := append([]workspaceRepo(nil), manifest.Repos...)
	sort.Slice(repos, func(i, j int) bool { return repos[i].RepoKey < repos[j].RepoKey })
	for _, repo := range repos {
		brainDir, err := brainDirForKey(opts.Env, repo.RepoKey)
		if err != nil {
			m.warnings = append(m.warnings, fmt.Sprintf("%s: %v", repo.RepoKey, err))
			continue
	if !replaced {
		manifest.Repos = append(manifest.Repos, repo)
	}
	sortWorkspaceRepos(manifest.Repos)
	if err := writeWorkspaceManifest(env, manifest); err != nil {
		return result, err
	}
	return result, nil
}

func acquireWorkspaceManifestLock(env EntireEnv, workspaceName string) (*fileLock, error) {
	dir, err := workspaceDir(env, workspaceName)
	if err != nil {
		return nil, err
	}
	workspaceRoot := filepath.Dir(dir)
	if err := rejectExistingSymlinkPathComponents(workspaceRoot, brainLockDirName); err != nil {
		return nil, err
	}
	// Keep membership locks outside the workspace directory so whole-workspace
	// deletion can hold the same lock without deleting an open lock file.
	return acquireFileLock(filepath.Join(workspaceRoot, brainLockDirName, workspaceName+"-"+workspaceManifestLockName), "workspace_manifest_locked", brainWriteLockTimeout)
}

func runWorkspaceRefresh(ctx context.Context, cmd *cobra.Command, opts Options, workspaceName string, full bool) error {
	manifest, err := loadWorkspaceManifest(opts.Env, workspaceName)
	if err != nil {
		return err
	}
	if full {
		refreshRepo := func(repoDir string) error { return watchDeterministicRefresh(ctx, cmd, opts, repoDir) }
		if err := workspaceFullRefresh(ctx, cmd.OutOrStdout(), opts, manifest, refreshRepo); err != nil {
			return err
		}
		// Keep the cross-repo V2 corpus current as part of the full refresh, so
		// users don't need a separate `workspace patterns refresh` build path.
		// Deterministic and token-free (aggregates already-built member corpora).
		if counts, werr := buildWorkspacePatternCorpus(opts.Env, manifest, opts.Now().UTC()); werr != nil {
			fmt.Fprintf(cmd.ErrOrStderr(), "warning: workspace patterns: %v\n", werr)
		} else {
			fmt.Fprintf(cmd.OutOrStdout(), "workspace patterns: %d cross-repo pattern(s) from %d/%d member corpora\n",
				counts.Patterns, counts.WithCorpus, counts.Members)
		}
	}
	freshness, err := workspaceFreshness(ctx, opts, manifest)
	if err != nil {
		return err
	}
	if err := writeWorkspaceRefreshResult(opts.Env, workspaceName, freshness, opts.Now().UTC()); err != nil {
		return err
	}
	if full {
		if artifact, err := writeWorkspaceGraphSnapshot(ctx, opts, manifest, 50); err != nil {
			fmt.Fprintf(cmd.ErrOrStderr(), "warning: workspace graph: %v\n", err)
		} else {
			fmt.Fprintf(cmd.OutOrStdout(), "workspace graph: %s\n", artifact)
		}
	}
	for _, repo := range freshness {
		fmt.Fprintf(cmd.OutOrStdout(), "%s %s\n", repo.RepoKey, repo.State)
	}
	return nil
}

