	var seen []int
	repoTick := func(repoDir string, agentCalls *int) {
		ticked = append(ticked, repoDir)
		seen = append(seen, *agentCalls)
		*agentCalls++ // simulate a token-spending step to prove the counter is shared, not per-repo
	}
