      "title": "<short title>",
      "trigger": "<when this applies / Use when>",
      "purpose": "<the procedure purpose>",
      "common_workflow": ["<repo-neutral step>", ...],
      "per_repo": [ {"repo_key": "<repo>", "commands": ["<actual command>", ...]}, ... ],
      "verdict": "accepted" | "rejected" | "needs_split" | "low_confidence"
    }
