// the accepted-deep-dossier gate with a precise message. The `patterns skills`
// LISTING uses loadSkillProposals instead, which additionally requires an
// accepted deep dossier.
func loadCorpusTaskCandidates(brainDir string) ([]taskCandidate, bool) {
	candidates, present, _ := loadCorpusTaskCandidatesChecked(brainDir)
	return candidates, present
}

func loadCorpusTaskCandidatesChecked(brainDir string) ([]taskCandidate, bool, error) {
	return queryTaskCandidatesChecked(brainDir, false)
}

// loadSkillProposals returns the formable skill proposals: a promotable task
// backed by an ACCEPTED deep dossier (which by construction excludes rejected/
// needs_split/low_confidence), PLUS the knowledge-sourced proposals (accepted
// `lesson:`/`convention:` dossiers — non-obvious recoveries and conventions, the
// archetypes that actually earn being a skill). Skill-memory suppression is
// applied by the caller.
func loadSkillProposals(brainDir string) ([]taskCandidate, bool) {
	candidates, present, _ := loadSkillProposalsChecked(brainDir)
	return candidates, present
}

func loadSkillProposalsChecked(brainDir string) ([]taskCandidate, bool, error) {
	cands, ok, err := queryTaskCandidatesChecked(brainDir, true)
	if err != nil {
		return nil, false, err
	}
	if !ok {
		return nil, false, nil
	}
	knowledge, err := loadKnowledgeSkillProposalsChecked(brainDir)
	if err != nil {
		return nil, false, err
	}
	return append(cands, knowledge...), true, nil
}

// loadKnowledgeSkillProposals returns proposals sourced from non-obvious
// knowledge rather than command sequences: accepted procedure (`lesson:`) and
// capability (`convention:`) deep dossiers. These carry their own archetype and
// are synthesized by converting the verified record, not by re-inferring from
// raw rows.
func loadKnowledgeSkillProposals(brainDir string) []taskCandidate {
	proposals, _ := loadKnowledgeSkillProposalsChecked(brainDir)
	return proposals
}

func loadKnowledgeSkillProposalsChecked(brainDir string) ([]taskCandidate, error) {
	db, present, err := openPatternCorpusReadDBIfPresent(brainDir)
	if err != nil {
		return nil, err
	}
	if !present {
		return nil, nil
	}
	defer db.Close()
	// A corpus that predates the additive deep_dossiers table has no accepted
	// dossiers, not a broken read.
	if ok, err := patternCorpusHasTable(db.DB, "deep_dossiers"); err != nil || !ok {
		return nil, err
	}
	rows, err := db.Query(`SELECT pattern_id, json_redacted FROM deep_dossiers
		WHERE verdict='accepted' AND (pattern_id LIKE 'lesson:%' OR pattern_id LIKE 'convention:%')
		ORDER BY pattern_id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var out []taskCandidate
	for rows.Next() {
		var id, blob string
		if err := rows.Scan(&id, &blob); err != nil {
			return out, err
		}
		var rec deepDossierRecord
		if err := json.Unmarshal([]byte(blob), &rec); err != nil {
			return nil, fmt.Errorf("%s: parse accepted knowledge skill proposal: %w", memoryErrStateCorrupt, err)
		}
		return err
	}
	wsDir, err := workspaceDir(opts.Env, name)
	if err != nil {
		return err
	}
	if err := validatePatternCorpusReadSafety(wsDir); err != nil {
		return err
	}
	procs, err := loadBrainProcedures(wsDir)
	if err != nil {
		return err
	}
	pracs, err := loadBrainPractices(wsDir)
	if err != nil {
		return err
	}
	members, err := loadMemberPatterns(opts, manifest)
	if err != nil {
		return err
	}
	views, _, corpusPresent, err := loadCorpusPatternViewsChecked(wsDir)
	if err != nil {
		return err
	}
	lastRun, hasLastRun, err := lastPatternRunChecked(wsDir)
	if err != nil {
		return err
	}
	covered := 0
	for _, repoKey := range members.repoOrder {
		if len(members.procsByRepo[repoKey]) > 0 || len(members.pracsByRepo[repoKey]) > 0 {
			covered++
		}
	}
	if err := bufferRetrievalCommandOutput(cmd, privacyPolicies, func() error {
		out := cmd.OutOrStdout()
		fmt.Fprintf(out, "workspace: %s\n", name)
		fmt.Fprintf(out, "member repos: %d (%d with patterns)\n", len(manifest.Repos), covered)
		fmt.Fprintf(out, "cross-repo procedures: %d\n", len(procs))
		fmt.Fprintf(out, "cross-repo practices: %d\n", len(pracs))
		if corpusPresent {
			fmt.Fprintf(out, "cross-repo V2 patterns: %d\n", len(views))
		}
		if hasLastRun {
			fmt.Fprintf(out, "last run: %s — %d pattern(s), %d synapse(s)\n", lastRun.At, lastRun.Patterns, lastRun.Synapses)
		}
		return nil
	}); err != nil {
		return err
	}
	for _, w := range members.warnings {
		fmt.Fprintf(cmd.ErrOrStderr(), "warning: %s\n", w)
	}
	return nil
}

// buildWorkspaceTaskCandidates merges member-repo task candidates by intent
// signature, keeping tasks shared by ≥2 repos. Evidence (procedures, facts,
// commands) is unioned and a per-repo breakdown is attached; the candidate is
// workspace-scoped.
func buildWorkspaceTaskCandidates(byRepo map[string][]taskCandidate, repoOrder []string, memberCount int, workspace string) []taskCandidate {
	type agg struct {
		base      taskCandidate
		repos     map[string]bool
		support   int
		reinf     reinforcementCounts
		cmds      map[string]bool
		procKeys  map[string]taskProcedure
		facts     map[string]bool
		intents   map[string]bool
		breakdown map[string]*patternRepoStat
	}
	aggs := map[string]*agg{}
	for _, repoKey := range repoOrder {
		for _, t := range byRepo[repoKey] {
			a := aggs[t.IntentSignature]
			if a == nil {
				a = &agg{base: t, repos: map[string]bool{}, cmds: map[string]bool{}, procKeys: map[string]taskProcedure{}, facts: map[string]bool{}, intents: map[string]bool{}, breakdown: map[string]*patternRepoStat{}}
				aggs[t.IntentSignature] = a
			}
package cli

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Pattern corpus surface integration (V2, Phase 5).
//
// Read-only projections of the corpus dossiers into existing brain surfaces.
// Everything here is best-effort and graceful: a missing/!built corpus yields no
// rows (never an error that breaks brief/get), output is already redacted at
// rest, and a verifier `rejected` verdict suppresses a consolidation entirely —
// the agent verifier is the authority that can remove, the deterministic gate the
// authority that promotes.

// loadCorpusPatternViews lists the V2 corpus `patterns` rows as unified
// patternViews — the primary analytical source for the public `patterns`
// surface (replacing the legacy procedure/practice JSON views). Each view
// carries its dossier state (current/stale + verifier verdict) and top anchor.
// Rejected dossiers are suppressed. Graceful: nil when no corpus exists.
func loadCorpusPatternViewsChecked(brainDir string) ([]patternView, map[string]patternView, bool, error) {
	db, present, err := openPatternCorpusReadDBIfPresent(brainDir)
	if err != nil {
		return nil, nil, false, err
	}
	if !present {
		return nil, nil, false, nil
	}
	defer db.Close()

	anchors, err := topAnchorByPatternChecked(db.DB)
	if err != nil {
		return nil, nil, true, err
	}
	rows, err := db.Query(`
		SELECT p.id, p.type, p.scope, COALESCE(p.repo_key,''), COALESCE(p.workspace,''),
		       COALESCE(p.intent_sig,''), COALESCE(p.gram,''), COALESCE(p.meta_id,''),
		       p.title, p.strength, p.strength_label, p.support, p.n_repos,
		       p.outcome_success, p.outcome_corrected, p.outcome_neutral,
		       COALESCE(d.status,''), COALESCE(d.verdict,'')
		FROM patterns p
		LEFT JOIN dossiers d ON d.pattern_id = p.id
		ORDER BY p.strength DESC`)
	if err != nil {
		return nil, nil, true, err
	}
	defer rows.Close()
	var views []patternView
	for rows.Next() {
		var (
			v                          patternView
			repoKey, workspace, metaID string
			succ, corr, neutral        int
			dossierStatus, verdict     string
		)
		if err := rows.Scan(&v.ID, &v.Type, &v.Scope, &repoKey, &workspace,
			&v.IntentSig, &v.Gram, &metaID, &v.Title, &v.Strength, &v.StrengthLabel, &v.Support, &v.Repos,
			&succ, &corr, &neutral, &dossierStatus, &verdict); err != nil {
			return nil, nil, true, err
		}
		if verdict == "rejected" { // the agent verifier is the authority that removes
			continue
		}
		v.Kind = metaID
		v.Workspace = workspace
		v.Title = redactText(v.Title)
		v.DossierStatus = dossierStatus
		v.Verdict = verdict
		rc := reinforcementCounts{Success: succ, Corrected: corr, Neutral: neutral}
		v.Reinforcement = &rc
		if a, ok := anchors[v.ID]; ok {
			ca := a
			v.Example = &ca
		}
		views = append(views, v)
	}
	if rows.Err() != nil {
		return nil, nil, true, rows.Err()
	}
	// Attach the per-repo breakdown to workspace-scope patterns.
	breakdown, err := loadWorkspaceRepoBreakdownChecked(db.DB)
	if err != nil {
		return nil, nil, true, err
	}
	for i := range views {
		if views[i].Scope == "workspace" {
			views[i].RepoBreakdown = breakdown[views[i].ID]
		}
	}
	idx := make(map[string]patternView, len(views))
	for _, v := range views {
		idx[v.ID] = v
	}
	return views, idx, true, nil
}

// loadCorpusPatternViews retains the historical best-effort helper for
// internal scoring/tests. Production response surfaces use the checked form.
func loadCorpusPatternViews(brainDir string) ([]patternView, map[string]patternView, bool) {
	views, index, present, _ := loadCorpusPatternViewsChecked(brainDir)
	return views, index, present
}

// topAnchorByPattern returns each pattern's rank-0 evidence anchor (redacted).
func topAnchorByPattern(db *sql.DB) map[string]episodeAnchor {
	anchors, _ := topAnchorByPatternChecked(db)
	return anchors
}

func topAnchorByPatternChecked(db *sql.DB) (map[string]episodeAnchor, error) {
	out := map[string]episodeAnchor{}
	rows, err := db.Query(`SELECT pattern_id, source_path, start_line FROM pattern_evidence WHERE rank=0`)
	if err != nil {
		return nil, err
	}

