   597	// buildWorkspaceTaskCandidates merges member-repo task candidates by intent
   598	// signature, keeping tasks shared by ≥2 repos. Evidence (procedures, facts,
   599	// commands) is unioned and a per-repo breakdown is attached; the candidate is
   600	// workspace-scoped.
   601	func buildWorkspaceTaskCandidates(byRepo map[string][]taskCandidate, repoOrder []string, memberCount int, workspace string) []taskCandidate {
   602		type agg struct {
   603			base      taskCandidate
   604			repos     map[string]bool
   605			support   int
   606			reinf     reinforcementCounts
   607			cmds      map[string]bool
   608			procKeys  map[string]taskProcedure
   609			facts     map[string]bool
   610			intents   map[string]bool
   611			breakdown map[string]*patternRepoStat
   612		}
   613		aggs := map[string]*agg{}
   614		for _, repoKey := range repoOrder {
   615			for _, t := range byRepo[repoKey] {
   616				a := aggs[t.IntentSignature]
   617				if a == nil {
   618					a = &agg{base: t, repos: map[string]bool{}, cmds: map[string]bool{}, procKeys: map[string]taskProcedure{}, facts: map[string]bool{}, intents: map[string]bool{}, breakdown: map[string]*patternRepoStat{}}
   619					aggs[t.IntentSignature] = a
   620				}
   621				a.repos[repoKey] = true
   622				a.support += t.Support
   623				a.reinf = addReinf(a.reinf, t.Reinforcement)
   624				for _, c := range t.Commands {
   625					a.cmds[c] = true
   626				}
   627				for _, p := range t.Procedures {
   628					key := strings.Join(p.Commands, "\x00")
   629					if cur, ok := a.procKeys[key]; !ok || p.Specificity > cur.Specificity {
   630						a.procKeys[key] = p
   631					}
   632				}
   633				for _, f := range t.MatchingFacts {
   634					a.facts[f] = true
   635				}
   636				for _, s := range t.SampleIntents {
   637					a.intents[s] = true
   638				}
   639				bd := a.breakdown[repoKey]
   640				if bd == nil {
   641					bd = &patternRepoStat{RepoKey: repoKey}
   642					a.breakdown[repoKey] = bd
   643				}
   644				bd.Support += t.Support
   645				bd.Reinforcement = addReinf(bd.Reinforcement, t.Reinforcement)
   646			}
   647		}
   648	
   649		var out []taskCandidate
   650		for sig, a := range aggs {
   651			repos := len(a.repos)
   652			if repos < workspaceMinRepos {
   653				continue
   654			}
   655			strength := workspacePracticeStrength("", repos, memberCount, a.support) // breadth+support blend
   656			out = append(out, taskCandidate{
   657				ID:              "task:ws:" + hexSHA(workspace+"\x00"+sig),
   658				Workspace:       workspace,
   659				IntentSignature: sig,
   660				Label:           a.base.Label,
   661				Support:         a.support,
