   597	// buildWorkspaceTaskCandidates merges member-repo task candidates by intent
   598	// signature, keeping tasks shared by ≥2 repos. Evidence (procedures, facts,
   599	// commands) is unioned and a per-repo breakdown is attached; the candidate is
   600	// workspace-scoped.
   601	func buildWorkspaceTaskCandidates(byRepo map[string][]taskCandidate, repoOrder []string, memberCount int, workspace string) []taskCandidate {
   602		type agg struct {
   603			base      taskCandidate
   604			repos     map[string]bool
   605			support   int
   606			reinf     reinforcementCounts
   607			cmds      map[string]bool
   608			procKeys  map[string]taskProcedure
   609			facts     map[string]bool
   610			intents   map[string]bool
   611			breakdown map[string]*patternRepoStat
   612		}
   613		aggs := map[string]*agg{}
   614		for _, repoKey := range repoOrder {
   615			for _, t := range byRepo[repoKey] {
   616				a := aggs[t.IntentSignature]
   617				if a == nil {
   618					a = &agg{base: t, repos: map[string]bool{}, cmds: map[string]bool{}, procKeys: map[string]taskProcedure{}, facts: map[string]bool{}, intents: map[string]bool{}, breakdown: map[string]*patternRepoStat{}}
   619					aggs[t.IntentSignature] = a
   620				}
   621				a.repos[repoKey] = true
   622				a.support += t.Support
   623				a.reinf = addReinf(a.reinf, t.Reinforcement)
   624				for _, c := range t.Commands {
   625					a.cmds[c] = true
   626				}
   627				for _, p := range t.Procedures {
   628					key := strings.Join(p.Commands, "\x00")
   629					if cur, ok := a.procKeys[key]; !ok || p.Specificity > cur.Specificity {
   630						a.procKeys[key] = p
   631					}
   632				}
   633				for _, f := range t.MatchingFacts {
   634					a.facts[f] = true
   635				}
   636				for _, s := range t.SampleIntents {
   637					a.intents[s] = true
   638				}
   639				bd := a.breakdown[repoKey]
   640				if bd == nil {
   641					bd = &patternRepoStat{RepoKey: repoKey}
   642					a.breakdown[repoKey] = bd
   643				}
   644				bd.Support += t.Support
   645				bd.Reinforcement = addReinf(bd.Reinforcement, t.Reinforcement)
   646			}
   647		}
   648	
   649		var out []taskCandidate
   650		for sig, a := range aggs {
   651			repos := len(a.repos)
   652			if repos < workspaceMinRepos {
   653				continue
   654			}
   655			strength := workspacePracticeStrength("", repos, memberCount, a.support) // breadth+support blend
   656			out = append(out, taskCandidate{
   657				ID:              "task:ws:" + hexSHA(workspace+"\x00"+sig),
   658				Workspace:       workspace,
   659				IntentSignature: sig,
   660				Label:           a.base.Label,
   661				Support:         a.support,
   662				Reinforcement:   a.reinf,
   663				Commands:        sortedSetKeys(a.cmds),
   664				Procedures:      sortedProcedures(a.procKeys),
   665				MatchingFacts:   sortedSetKeys(a.facts),
   666				SampleIntents:   sortedSetKeys(a.intents),
   667				Repos:           repos,
   668				RepoBreakdown:   sortedBreakdown(a.breakdown),
   669				Strength:        math.Round(strength*1000) / 1000,
   670				StrengthLabel:   strengthLabel(strength),
   671			})
   672		}
   673		sort.SliceStable(out, func(i, j int) bool {
   674			if out[i].Strength != out[j].Strength {
   675				return out[i].Strength > out[j].Strength
   676			}
   677			return out[i].ID < out[j].ID
   678		})
   679		return out
   680	}
   681	
   682	// runWorkspaceSkillsList lists accepted cross-repo FAMILY proposals (SR5): the
   683	// verified semantic groupings, not the raw exact-aggregated rows. Run
   684	// `workspace patterns verify` to produce them.
   685	func runWorkspaceSkillsList(ctx context.Context, cmd *cobra.Command, opts Options, name string, asJSON bool, limit int) error {
   686		manifest, err := loadWorkspaceManifest(opts.Env, name)
   687		if err != nil && !os.IsNotExist(err) {
   688			return err
   689		}
   690		var privacyPolicies []retrievalPrivacyPolicy
   691		if err == nil {
   692			privacyPolicies, err = captureWorkspaceDerivedReadPolicies(opts.Env, manifest)
   693			if err != nil {
   694				return err
   695			}
   696		}
   697		wsDir, err := workspaceDir(opts.Env, name)
   698		if err != nil {
   699			return err
   700		}
   701		if err := validatePatternCorpusReadSafety(wsDir); err != nil {
   702			return err
   703		}
   704		families, err := loadAcceptedWorkspaceFamiliesChecked(wsDir)
   705		if err != nil {
   706			return err
   707		}
   708		if limit > 0 && len(families) > limit {
   709			families = families[:limit]
   710		}
   711		return bufferRetrievalCommandOutput(cmd, privacyPolicies, func() error {
   712			if asJSON {
   713				return writeJSON(cmd, families)
   714			}
   715			out := cmd.OutOrStdout()
   716			if len(families) == 0 {
   717				fmt.Fprintf(out, "workspace %s: no accepted cross-repo families (run `entire brain workspace patterns verify %s`)\n", name, name)
   718				return nil
   719			}
   720			for _, f := range families {
   721				repos := make([]string, 0, len(f.PerRepo))
   722				for _, v := range f.PerRepo {
   723					repos = append(repos, v.RepoKey)
   724				}
   725				fmt.Fprintf(out, "[family] %s  (%d repos: %s)\n", redactText(f.Title), f.repoCount(), strings.Join(repos, ", "))
   726				fmt.Fprintf(out, "    trigger: %s\n", redactText(f.Trigger))
   727				fmt.Fprintf(out, "    id %s\n", f.ID)
   728			}
   729			return nil
   730		})
   731	}
