   733	func runWorkspaceSkillsForm(ctx context.Context, cmd *cobra.Command, opts Options, name string, s skillFormOptions) error {
   734		manifest, err := loadWorkspaceManifest(opts.Env, name)
   735		if err != nil {
   736			return err
   737		}
   738		privacyPolicies, err := captureWorkspaceDerivedReadPolicies(opts.Env, manifest)
   739		if err != nil {
   740			return err
   741		}
   742		wsDir, err := workspaceDir(opts.Env, name)
   743		if err != nil {
   744			return err
   745		}
   746		if err := validatePatternCorpusReadSafety(wsDir); err != nil {
   747			return err
   748		}
   749		agent := s.agent
   750		if agent == "" || agent == "auto" {
   751			agent = defaultRefreshAgent(ctx, opts.Runner, ".")
   752		}
   753		if agent == "none" {
   754			return fmt.Errorf("skill synthesis requires an agent (codex or claude-code); none found on PATH")
   755		}
   756		return runPrivacyLinearizedPatternMutation(cmd, privacyPolicies, func() error {
   757			// Resolve the accepted source only after every member policy/lock is
   758			// pinned. Workspace verification uses the same locks, so a concurrent
   759			// family replacement cannot leave synthesis using a stale dossier.
   760			fam, ok, err := getAcceptedWorkspaceFamilyChecked(wsDir, s.taskID)
   761			if err != nil {
   762				return err
   763			}
   764			if !ok {
   765				return fmt.Errorf("no accepted workspace family %q: run `entire brain workspace patterns verify %s` (explicit, egress-gated), then `entire brain workspace patterns skills %s`", s.taskID, name, name)
   766			}
   767			// A synthetic candidate carries id/name/scope + per-repo breakdown for
   768			// the skill-memory record; synthesis itself runs from the family.
   769			breakdown := make([]patternRepoStat, 0, len(fam.PerRepo))
   770			for _, v := range fam.PerRepo {
   771				breakdown = append(breakdown, patternRepoStat{RepoKey: v.RepoKey, Support: 1})
   772			}
   773			cand := taskCandidate{
   774				ID: fam.ID, Label: fam.Title, Workspace: name, Repos: fam.repoCount(),
   775				RepoBreakdown: breakdown, Commands: fam.CommonWorkflow, Support: fam.repoCount(),
   776				Strength: 0.7, StrengthLabel: "high",
   777			}
   778			return synthesizeAndForm(ctx, cmd, cand, nil, &fam, wsDir, ".", agent, defaultDistillAgentRunner(agent), s, opts.Now().UTC())
   779		})
   780	}
