package cli

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// These use the public root command with a durable episode fixture. They pin
// the packet users receive, rather than the ranking helpers that build it.
func TestBriefOutputRootJSONAndTextContracts(t *testing.T) {
	opts, repoDir, _ := commandRegressionFixture(t)
	for _, rel := range []string{"providers/responses.go", "client/previous_response.go"} {
		path := filepath.Join(repoDir, rel)
		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil { t.Fatal(err) }
		if err := os.WriteFile(path, []byte("package client\n// metadata previous_response_id\n"), 0o600); err != nil { t.Fatal(err) }
	}
	task := "repair Responses API metadata and previous_response_id contract"
	out, err := execute(t, NewRootCommand(opts), "brief", task, "--json", "--limit", "8")
	if err != nil { t.Fatalf("brief json: %v\n%s", err, out) }
	var report map[string]any
	if err := json.Unmarshal([]byte(out), &report); err != nil { t.Fatalf("decode: %v\n%s", err, out) }
	if report["task"] != task || report["status"] == nil || report["guidance"] == nil { t.Fatalf("public report missing task/status/guidance: %#v", report) }
	if strings.Contains(out, "private metadata") { t.Fatalf("brief leaked fixture-private text: %s", out) }
	text, err := execute(t, NewRootCommand(opts), "brief", task, "--limit", "8")
	if err != nil || !strings.Contains(text, "Task:") || !strings.Contains(text, task) { t.Fatalf("brief text: %v\n%s", err, text) }
}

func TestBriefOutputRejectsInvalidBudgetAtRoot(t *testing.T) {
	opts, _, _ := commandRegressionFixture(t)
	out, err := execute(t, NewRootCommand(opts), "brief", "metadata", "--limit", "0", "--json")
